configuration.styles:

                /* To show multiple spaces in html between words */
                .step-details{
                	white-space: pre-wrap;
                }

.desc-table {
    border-collapse: collapse;
    margin: 10px 0;
    font-size: 0.9em;
    font-family: sans-serif;
    min-width: 400px;
}

.desc-table th,
.desc-table td {
    padding: 3px;
}
.desc-table tbody tr {
    border-bottom: 1px solid #dddddd;
}

.desc-table tbody tr:nth-of-type(even) {
    background-color: #f3f3f3;
}

.desc-table tbody tr:last-of-type {
    border-bottom: 2px solid #cacaca;
}

.no{
    width: 6ch;
    text-align: center;
}
.steps{
    min-width: 200px;
}
.header th
{
    background-color: #0a6ec4;
    color: #ffffff !important;
    text-align: left;
    font-size: small;
    font-weight: bold;
}
.testDescription
{
    padding-left: 1.5ch !important;
}


#btnReadMoreLessId {
  	background-color: #f3f3f3;
  	color: #0a6ec4;
  	font-size: 14px;
  	width: 100px;
  	height: 25px;
  	border: none;
  	font-weight: bold;
 	display: inline;
  	position: relative;
  	top: 50%;
  	left: 40%;
  	transform: translate(-50%, -50%);
  	margin: 10px 0px -4px 0px;
}

.test-attributes {
  	float: left;
  	margin-bottom: 10px;
}

#stepsCount {
  	float: left;
}

.after-desc-table {
  	display: inline-block;
  	width: 100%;
}

.count{
    display: flex;
    margin-bottom: 1%;
}

.test-desc {
    margin-bottom: 0px; 
}

.test-steps {
  	margin-top: 0px;
}
tr[onclick*='wrapStartBlock'] { 
  cursor: pointer; 
}

#cover-spin {
    position:fixed;
    width:100%;
    left:0;right:0;top:0;bottom:0;
    background-color: rgba(0,0,0,0.2);
    z-index:9999;
    display:none;
}

@-webkit-keyframes spin {
	from {-webkit-transform:rotate(0deg);}
	to {-webkit-transform:rotate(360deg);}
}

@keyframes spin {
	from {transform:rotate(0deg);}
	to {transform:rotate(360deg);}
}

#cover-spin::after {
    content:'';
    display:block;
    position:absolute;
    left:48%;top:40%;
    width:50px;height:50px;
    border-style:solid;
    border-color:#0a6ec4;
    border-top-color:transparent;
    border-width: 5px;
    border-radius:50%;
    -webkit-animation: spin .8s linear infinite;
    animation: spin .8s linear infinite;
}


.switch {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 21px;
}

.switch input { 
  opacity: 0;
  width: 0;
  height: 0;
}

.sliderx {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  -webkit-transition: .4s;
  transition: .4s;
}

.sliderx:before {
  position: absolute;
  content: "";
  height: 14px;
  width: 13px;
  left: 7px;
  bottom: 4px;
  background-color: white;
  -webkit-transition: .4s;
  transition: .4s;
}

input:checked + .sliderx {
  background-color: #2196F3;
}

input:focus + .sliderx {
  box-shadow: 0 0 1px #2196F3;
}

input:checked + .sliderx:before {
  -webkit-transform: translateX(14px);
  -ms-transform: translateX(14px);
  transform: translateX(14px);
}

/* Rounded sliders */
.sliderx.round {
  border-radius: 34px;
}

.sliderx.round:before {
  border-radius: 50%;
}

.checkBoxParent
{
  position: absolute;
  right: 57.4%;

}

html.with-featherlight{overflow:hidden}.featherlight{display:none;position:fixed;top:0;right:0;bottom:0;left:0;z-index:2147483647;text-align:center;white-space:nowrap;cursor:pointer;background:#333;background:rgba(0,0,0,0)}.featherlight:last-of-type{background:rgba(0,0,0,.8)}.featherlight:before{content:'';display:inline-block;height:100%;vertical-align:middle}.featherlight .featherlight-content{position:relative;text-align:left;vertical-align:middle;display:inline-block;overflow:auto;padding:25px 25px 0;border-bottom:25px solid transparent;margin-left:5%;margin-right:5%;max-height:95%;background:#fff;cursor:auto;white-space:normal}.featherlight .featherlight-inner{display:block}.featherlight link.featherlight-inner,.featherlight script.featherlight-inner,.featherlight style.featherlight-inner{display:none}.featherlight .featherlight-close-icon{position:absolute;z-index:9999;top:0;right:0;line-height:25px;width:25px;cursor:pointer;text-align:center;font-family:Arial,sans-serif;background:#fff;background:rgba(255,255,255,.3);color:#000;border:0;padding:0}.featherlight .featherlight-close-icon::-moz-focus-inner{border:0;padding:0}.featherlight .featherlight-image{width:100%}.featherlight-iframe .featherlight-content{border-bottom:0;padding:0;-webkit-overflow-scrolling:touch}.featherlight iframe{border:0}.featherlight *{-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box}@media only screen and (max-width:1024px){.featherlight .featherlight-content{margin-left:0;margin-right:0;max-height:98%;padding:10px 10px 0;border-bottom:10px solid transparent}}@media print{html.with-featherlight>*>:not(.featherlight){display:none}}
